import React from 'react';
import TestRenderer,{act} from 'react-test-renderer';
import assert from 'node:assert/strict';
import Reader from '../../../client/src/pages/reader.tsx';
const values=new Map();
const source={id:101,title:'LIBRO_A',author:'AUTOR_A',genre:'todos',chapters:[{title:'Uno',content:'TEXTO_LIBRO_A'},{title:'Dos',content:'CAPITULO_DOS_A'}]};
values.set('novareads_saved',JSON.stringify([source]));values.set('reading_maxchapter_101','1');
globalThis.readerStorage={getItem:key=>values.get(key)||null,setItem:(key,value)=>values.set(key,String(value))};
globalThis.readerBooks=new Map([[101,source]]);
globalThis.readerRoute={bookId:'101',chapterId:'1'};globalThis.progressWrites=[];
globalThis.window={location:{pathname:'/read/101/1'},history:{replaceState:(_a,_b,path)=>{window.location.pathname=path}},addEventListener(){},removeEventListener(){}};
let view;
await act(async()=>{view=TestRenderer.create(React.createElement(Reader));});
const before=JSON.stringify(view.toJSON());assert.ok(before.includes('TEXTO_LIBRO_A'));
globalThis.readerRoute={bookId:'202',chapterId:'1'};window.location.pathname='/read/202/1';
await act(async()=>{view.update(React.createElement(Reader));});
const pending=JSON.stringify(view.toJSON());assert.ok(!pending.includes('TEXTO_LIBRO_A'));assert.ok(!pending.includes('LIBRO_A'));
assert.deepEqual(globalThis.progressWrites.filter(row=>row.bookId===202),[]);
globalThis.readerBooks.set(202,{id:202,title:'LIBRO_B',author:'AUTOR_B',genre:'todos',chapters:[{title:'Uno',content:'TEXTO_LIBRO_B'}]});
await act(async()=>{view.update(React.createElement(Reader));});
const loaded=JSON.stringify(view.toJSON());assert.ok(loaded.includes('TEXTO_LIBRO_B'));assert.ok(!loaded.includes('TEXTO_LIBRO_A'));
const writes=globalThis.progressWrites.filter(row=>row.bookId===202);assert.ok(writes.length);assert.ok(writes.every(row=>row.maxChapter===0));
globalThis.readerBooks.set(202,null);
await act(async()=>{view.update(React.createElement(Reader));});
const absent=JSON.stringify(view.toJSON());assert.ok(!absent.includes('TEXTO_LIBRO_A'));assert.ok(!absent.includes('TEXTO_LIBRO_B'));
await act(async()=>view.unmount());
